package fft

// Float32 pair and quad forms of the DCT-IV of length 64 (go-avkit/decode#77:
// HE-AAC's QMF banks run it six times per slot in single precision, and the float32
// of the float64 pair kernel, DCTMixedPair, widens, computes in double and narrows).
// On amd64 with AVX2 and FMA3 a DCTPlan32 of type 4 and length 64 runs a kernel in
// single precision throughout (dct4_64_f32_amd64.s, generated by internal/gendct4:
// the program of the float64 pair kernel, one complex value of every stream per
// register); elsewhere, and for other plans, the forms are the single calls. The
// results are within the plan's error bound, not bit for bit those of DCT: the
// kernel fuses multiply-adds and orders the arithmetic differently from the
// generic float32 plan.

// DCTPair writes the DCT of src0 into dst0 and that of src1 into dst1, like
// p.DCT(dst0, src0, norm) followed by p.DCT(dst1, src1, norm), and returns
// dst0[:Len()] and dst1[:Len()]. The slice rules are DCT's for each stream, all
// checked before anything is written. dst0 and dst1 must not overlap each other or
// the other stream's source (if they do the two calls run in order, as written);
// dst0 may alias src0 and dst1 may alias src1.
func (p *DCTPlan32) DCTPair(dst0, dst1, src0, src1 []float32, norm Norm) (r0, r1 []float32) {
	return p.runPair(dst0, dst1, src0, src1, norm, false)
}

// IDCTPair is DCTPair for the inverse transform.
func (p *DCTPlan32) IDCTPair(dst0, dst1, src0, src1 []float32, norm Norm) (r0, r1 []float32) {
	return p.runPair(dst0, dst1, src0, src1, norm, true)
}

func (p *DCTPlan32) runPair(dst0, dst1, src0, src1 []float32, norm Norm, inverse bool) (r0, r1 []float32) {
	n := p.k.n
	norm.scale(1, false) // panics on an unknown Norm
	if len(dst0) < n || len(dst1) < n || len(src0) < n || len(src1) < n {
		panic("fft: DCTPlan32 slice shorter than the plan's length")
	}
	if p.quad && !overlap(dst0[:n], src1[:n]) && !overlap(dst1[:n], src0[:n]) && !overlap(dst0[:n], dst1[:n]) {
		dct4n64F32Pair(dst0, dst1, src0, src1, float32(norm.scale(2*n, inverse)))
		return dst0[:n], dst1[:n]
	}
	return p.run(dst0, src0, norm, inverse), p.run(dst1, src1, norm, inverse)
}

// DCTQuad is DCTPair on four streams: dst[i] receives the DCT of src[i]. On a plan
// of length 64 with the kernel it costs about as much as one DCTPair per two
// streams less; otherwise it is four single calls. The streams must not overlap
// except that dst[i] may alias src[i] (otherwise the four calls run in order, as
// written).
func (p *DCTPlan32) DCTQuad(dst, src [4][]float32, norm Norm) [4][]float32 {
	return p.runQuad(dst, src, norm, false)
}

// IDCTQuad is DCTQuad for the inverse transform.
func (p *DCTPlan32) IDCTQuad(dst, src [4][]float32, norm Norm) [4][]float32 {
	return p.runQuad(dst, src, norm, true)
}

func (p *DCTPlan32) runQuad(dst, src [4][]float32, norm Norm, inverse bool) [4][]float32 {
	n := p.k.n
	norm.scale(1, false)
	for i := range dst {
		if len(dst[i]) < n || len(src[i]) < n {
			panic("fft: DCTPlan32 slice shorter than the plan's length")
		}
	}
	if p.quad && quadDisjoint(&dst, &src, n) {
		dct4n64F32Quad(&dst, &src, float32(norm.scale(2*n, inverse)))
	} else {
		for i := range dst {
			p.run(dst[i], src[i], norm, inverse)
		}
	}
	for i := range dst {
		dst[i] = dst[i][:n]
	}
	return dst
}

// quadDisjoint reports whether no destination overlaps another destination or
// another stream's source.
func quadDisjoint(dst, src *[4][]float32, n int) bool {
	for i := range dst {
		for j := range dst {
			if j == i {
				continue
			}
			if overlap(dst[i][:n], dst[j][:n]) || overlap(dst[i][:n], src[j][:n]) {
				return false
			}
		}
	}
	return true
}
